begin;
select no_plan();
set local test.request_payload = '{"name":"Fictional Onboarding Shop","category":"Grocery","neighborhood":"Test neighborhood","consent":true,"user_id":"10000000-0000-0000-0000-000000000004","status":"approved"}';
set local role anon;
select throws_ok($$select * from public.owner_shop_requests$$, '42501', null, 'anonymous cannot read requests');
select throws_ok($$select public.submit_owner_shop_request('81000000-0000-0000-0000-000000000001', current_setting('test.request_payload')::jsonb)$$, '42501', null, 'anonymous cannot submit');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000005', true);
select throws_ok($$select public.submit_owner_shop_request('81000000-0000-0000-0000-000000000001', current_setting('test.request_payload')::jsonb || '{"consent":false}')$$, '22023', 'Check shop details and ownership consent', 'consent required');
select throws_ok($$select public.submit_owner_shop_request('81000000-0000-0000-0000-000000000001', current_setting('test.request_payload')::jsonb || '{"name":""}')$$, '22023', 'Check shop details and ownership consent', 'empty name rejected in database');
select is(public.submit_owner_shop_request('81000000-0000-0000-0000-000000000001', current_setting('test.request_payload')::jsonb), '81000000-0000-0000-0000-000000000001'::uuid, 'confirmed user submits request');
select is((select user_id from public.owner_shop_requests), '10000000-0000-0000-0000-000000000005'::uuid, 'payload cannot forge owner identity');
select is((select status from public.owner_shop_requests), 'pending', 'payload cannot approve itself');
select is((select count(*)::int from public.shop_memberships), 0, 'request grants no memberships');
select is(public.submit_owner_shop_request('81000000-0000-0000-0000-000000000001', current_setting('test.request_payload')::jsonb), '81000000-0000-0000-0000-000000000001'::uuid, 'duplicate retry is safe');
select throws_ok($$select public.submit_owner_shop_request('81000000-0000-0000-0000-000000000002', current_setting('test.request_payload')::jsonb)$$, '23505', 'A shop request already exists for this account', 'multiple requests cannot be created');
select throws_ok($$update public.owner_shop_requests set status='approved'$$, '42501', null, 'owner cannot directly change request status');
select throws_ok($$select public.review_owner_shop_request('81000000-0000-0000-0000-000000000001',true,'onboarding-test',true,'in_person')$$, '42501', 'Administrator access required', 'owner cannot self-approve');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select is((select count(*)::int from public.owner_shop_requests), 0, 'other owner cannot see request');
reset role;
update auth.users set email_confirmed_at = null where id = '10000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000003', true);
select throws_ok($$select public.submit_owner_shop_request('81000000-0000-0000-0000-000000000002', current_setting('test.request_payload')::jsonb)$$, '42501', 'Confirm your email before requesting a shop', 'unconfirmed account cannot submit');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000004', true);
select is((select count(*)::int from public.owner_shop_requests), 1, 'admin can review pending requests');
select throws_ok($$select public.review_owner_shop_request('81000000-0000-0000-0000-000000000001',true,'onboarding-test',false,'in_person')$$, '22023', 'Verify ownership before assigning access', 'admin must independently verify ownership');
select lives_ok($$select public.review_owner_shop_request('81000000-0000-0000-0000-000000000001',true,'onboarding-test',true,'in_person')$$, 'verified admin approval creates shop');
select is((select status from public.owner_shop_requests), 'approved', 'request marked approved atomically');
select is((select count(*)::int from public.public_shops where slug='onboarding-test'), 1, 'approved business profile becomes public');
select lives_ok($$select public.review_owner_shop_request('81000000-0000-0000-0000-000000000001',true,'onboarding-test',true,'in_person')$$, 'approval retry does not create another shop');
select is((select count(*)::int from public.shops where slug='onboarding-test'), 1, 'only one approved shop exists');
select throws_ok($$select public.review_owner_shop_request('81000000-0000-0000-0000-000000000001',false)$$, '40001', 'Request already reviewed', 'stale rejection cannot undo approval');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000005', true);
select is((select count(*)::int from public.shop_memberships), 1, 'approved owner sees its membership');
select is((select role from public.shop_memberships), 'owner', 'approved account receives owner role');
select is((select count(*)::int from public.shops where slug='onboarding-test'), 1, 'approved owner can access shop');
select * from finish();
rollback;
